    stack<int> inbox;            // new items are pushed here
    stack<int> outbox;           // items leave from here: oldest on top
    int front = 0;               // the oldest item in the inbox

public:
    void push(int x) {
        if (inbox.empty()) front = x;        // the first item into an empty inbox is its oldest
        inbox.push(x);
    }

    int pop() {
        if (outbox.empty()) {
            while (!inbox.empty()) {         // pour: the order flips
                outbox.push(inbox.top());
                inbox.pop();
            }
        }
        int x = outbox.top();
        outbox.pop();
        return x;
    }

    int peek() {
        // anything on the outbox is older than everything in the inbox
        return outbox.empty() ? front : outbox.top();
    }

    bool empty() {
        return inbox.empty() && outbox.empty();
    }
};
